import sys; sys.path.insert(0,'/bot/src')
import drv, math, time
def enc_r():
    for _ in range(4):
        e=drv.enc()
        if e and None not in e: return e
        time.sleep(0.08)
    return None
def prof():
    pts=drv.scan()
    pr={}
    for x,y,z in pts:
        if -0.03<z<0.4:
            az=int((math.degrees(math.atan2(x,y))+180)//10)*10-180
            r=math.hypot(x,y)
            if az not in pr or r<pr[az]: pr[az]=r
    return pr
p0=prof(); e0=enc_r()
drv._w('d1','10'); drv._w('d7','10'); time.sleep(8.0); drv.stop(); time.sleep(0.3)
e1=enc_r(); p1=prof()
ks=sorted(set(p0)|set(p1))
print("az: before -> after")
for k in ks: print(f"{k:+5d}: {p0.get(k,99):.2f} -> {p1.get(k,99):.2f}")
if e0 and e1: print("counts:",e1[0]-e0[0], e1[1]-e0[1])
EOF

